AssistantMessageToolRequest(name='create', tool_call_id='tooluse_ATEo9hQh1fpJXo4ayIXeOM', arguments={'file_text': ':root {
    --bg-primary: #0f172a;
    --bg-secondary: #1e293b;
    --bg-tertiary: #334155;
    --border-color: #475569;
    --text-primary: #f1f5f9;
    --text-secondary: #cbd5e1;
    --accent-color: #3b82f6;
    --accent-hover: #2563eb;
    --success-color: #10b981;
    --success-light: #d1fae5;
    --error-color: #ef4444;
    --focus-ring: #60a5fa;
}

* {
    margin: 0;
    padding: 0;
    box-sizing: border-box;
}

html {
    scroll-behavior: smooth;
}

body {
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, 'Helvetica Neue', Arial, sans-serif;
    background: linear-gradient(135deg, var(--bg-primary) 0%, #1a1f35 100%);
    color: var(--text-primary);
    line-height: 1.6;
    min-height: 100vh;
    padding: 20px;
}

.container {
    max-width: 700px;
    margin: 0 auto;
}

header {
    text-align: center;
    margin-bottom: 40px;
    padding: 20px 0;
}

h1 {
    font-size: 2.5rem;
    margin-bottom: 10px;
    background: linear-gradient(135deg, var(--accent-color), #60a5fa);
    -webkit-background-clip: text;
    -webkit-text-fill-color: transparent;
    background-clip: text;
}

.subtitle {
    color: var(--text-secondary);
    font-size: 1.1rem;
}

h2 {
    font-size: 1.75rem;
    margin-bottom: 20px;
    color: var(--text-primary);
}

.form-field {
    background: var(--bg-secondary);
    border: 1px solid var(--border-color);
    border-radius: 12px;
    padding: 24px;
    margin-bottom: 24px;
    transition: all 0.3s ease;
}

.form-field:hover {
    border-color: var(--accent-color);
    box-shadow: 0 0 20px rgba(59, 130, 246, 0.1);
}

.form-field:focus-within {
    box-shadow: 0 0 0 3px rgba(96, 165, 250, 0.1);
}

.question-title {
    display: flex;
    align-items: flex-start;
    font-size: 1.1rem;
    font-weight: 600;
    color: var(--text-primary);
    margin-bottom: 12px;
    cursor: pointer;
}

.question-number {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    min-width: 28px;
    height: 28px;
    background: var(--accent-color);
    color: white;
    border-radius: 50%;
    font-weight: 700;
    margin-right: 12px;
    font-size: 0.9rem;
}

.help-text {
    color: var(--text-secondary);
    font-size: 0.9rem;
    margin: -8px 0 16px 40px;
    font-style: italic;
}

.options-group {
    border: none;
    display: flex;
    flex-direction: column;
    gap: 12px;
}

.option {
    display: flex;
    align-items: center;
    padding: 12px 16px;
    background: var(--bg-primary);
    border: 2px solid var(--border-color);
    border-radius: 8px;
    cursor: pointer;
    transition: all 0.2s ease;
}

.option:hover {
    border-color: var(--accent-color);
    background: rgba(59, 130, 246, 0.05);
}

.option input[type="checkbox"] {
    position: absolute;
    opacity: 0;
    width: 0;
    height: 0;
}

.checkbox-custom {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    width: 20px;
    height: 20px;
    min-width: 20px;
    border: 2px solid var(--border-color);
    border-radius: 6px;
    background: transparent;
    transition: all 0.2s ease;
    margin-right: 12px;
}

.option input[type="checkbox"]:checked + .checkbox-custom {
    background: var(--accent-color);
    border-color: var(--accent-color);
    box-shadow: inset 0 0 0 2px var(--bg-secondary);
}

.option input[type="checkbox"]:checked + .checkbox-custom::after {
    content: '✓';
    color: white;
    font-weight: bold;
    font-size: 14px;
}

.option input[type="checkbox"]:focus + .checkbox-custom {
    outline: 2px solid var(--focus-ring);
    outline-offset: 2px;
}

.option-text {
    color: var(--text-primary);
    font-weight: 500;
}

.form-actions {
    display: flex;
    justify-content: center;
    margin-top: 32px;
    margin-bottom: 40px;
}

.submit-btn,
.reset-btn {
    padding: 14px 48px;
    font-size: 1rem;
    font-weight: 600;
    border: none;
    border-radius: 8px;
    cursor: pointer;
    transition: all 0.3s ease;
    text-transform: uppercase;
    letter-spacing: 0.5px;
}

.submit-btn {
    background: linear-gradient(135deg, var(--accent-color), var(--accent-hover));
    color: white;
    box-shadow: 0 4px 15px rgba(59, 130, 246, 0.3);
}

.submit-btn:hover {
    transform: translateY(-2px);
    box-shadow: 0 6px 20px rgba(59, 130, 246, 0.4);
}

.submit-btn:active {
    transform: translateY(0);
}

.submit-btn:focus {
    outline: 2px solid var(--focus-ring);
    outline-offset: 2px;
}

.reset-btn {
    background: var(--bg-secondary);
    color: var(--text-primary);
    border: 2px solid var(--border-color);
}

.reset-btn:hover {
    border-color: var(--accent-color);
    background: var(--bg-tertiary);
}

.results-section {
    background: var(--bg-secondary);
    border: 1px solid var(--border-color);
    border-radius: 12px;
    padding: 32px;
    margin-bottom: 40px;
    animation: slideUp 0.4s ease;
}

@keyframes slideUp {
    from {
        opacity: 0;
        transform: translateY(20px);
    }
    to {
        opacity: 1;
        transform: translateY(0);
    }
}

.result-item {
    background: var(--bg-primary);
    border-left: 4px solid var(--border-color);
    padding: 16px;
    margin-bottom: 16px;
    border-radius: 6px;
    transition: all 0.2s ease;
}

.result-item.success {
    border-left-color: var(--success-color);
    background: rgba(16, 185, 129, 0.05);
}

.result-item.incorrect {
    border-left-color: var(--error-color);
    background: rgba(239, 68, 68, 0.05);
}

.result-title {
    font-weight: 600;
    margin-bottom: 8px;
    color: var(--text-primary);
}

.result-text {
    color: var(--text-secondary);
    font-size: 0.95rem;
    margin: 4px 0;
}

.sr-only {
    position: absolute;
    width: 1px;
    height: 1px;
    padding: 0;
    margin: -1px;
    overflow: hidden;
    clip: rect(0, 0, 0, 0);
    white-space: nowrap;
    border-width: 0;
}

@media (max-width: 600px) {
    h1 {
        font-size: 1.75rem;
    }

    .form-field {
        padding: 18px;
        margin-bottom: 18px;
    }

    .question-title {
        font-size: 1rem;
    }

    .submit-btn,
    .reset-btn {
        padding: 12px 32px;
        font-size: 0.95rem;
    }

    .results-section {
        padding: 20px;
    }
}
