    font-size: 1.1rem;
    font-weight: 600;
    color: var(--text-primary);
    margin-bottom: 12px;
    cursor: pointer;
}

.question-number {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    min-width: 28px;
    height: 28px;
    background: var(--accent-color);
    color: white;
    border-radius: 50%;
    font-weight: 700;
    margin-right: 12px;
    font-size: 0.9rem;
}

.help-text {
    color: var(--text-secondary);
    font-size: 0.9rem;
    margin: -8px 0 16px 40px;
    font-style: italic;
}

.options-group {
    border: none;
    display: flex;
    flex-direction: column;
    gap: 12px;
}

.option {
    display: flex;
    align-items: center;
    padding: 12px 16px;
    background: var(--bg-primary);
    border: 2px solid var(--border-color);
    border-radius: 8px;
    cursor: pointer;
    transition: all 0.2s ease;
}

.option:hover {
    border-color: var(--accent-color);
    background: rgba(59, 130, 246, 0.05);
}

.option input[type="checkbox"] {
    position: absolute;
    opacity: 0;
    width: 0;
    height: 0;
}

.checkbox-custom {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    width: 20px;
    height: 20px;
    min-width: 20px;
    border: 2px solid var(--border-color);
    border-radius: 6px;
    background: transparent;
    transition: all 0.2s ease;
    margin-right: 12px;
}

.option input[type="checkbox"]:checked + .checkbox-custom {
    background: var(--accent-color);
    border-color: var(--accent-color);
    box-shadow: inset 0 0 0 2px var(--bg-secondary);
}

.option input[type="checkbox"]:checked + .checkbox-custom::after {
    content: '✓';
    color: white;
    font-weight: bold;
    font-size: 14px;
}

.option input[type="checkbox"]:focus + .checkbox-custom {
    outline: 2px solid var(--focus-ring);
    outline-offset: 2px;
}

.option-text {
    color: var(--text-primary);
    font-weight: 500;
}

.form-actions {
