    border: 2px solid var(--border-color);
}

.reset-btn:hover {
    border-color: var(--accent-color);
    background: var(--bg-tertiary);
}

.results-section {
    background: var(--bg-secondary);
    border: 1px solid var(--border-color);
    border-radius: 12px;
    padding: 32px;
    margin-bottom: 40px;
    animation: slideUp 0.4s ease;
}

@keyframes slideUp {
    from {
