    question1: ['python', 'javascript', 'ruby'],
    question2: ['html', 'php'],
    question3: ['haskell', 'lisp', 'kotlin']
};

const quizForm = document.getElementById('quizForm');
const resultsDiv = document.getElementById('results');
const resultsContent = document.getElementById('resultsContent');

quizForm.addEventListener('submit', function(e) {
    e.preventDefault();
    evaluateQuiz();
});

function evaluateQuiz() {
    const results = [];

    // Check each question
    for (let i = 1; i <= 3; i++) {
        const questionName = `question${i}`;
        const selected = getSelectedAnswers(questionName);
        const correct = correctAnswers[questionName];

        // Check if selection matches correct answers
        const isCorrect = arraysEqual(selected, correct);

        results.push({
            questionNumber: i,
            selected: selected,
            correct: correct,
            isCorrect: isCorrect
        });
    }

    displayResults(results);
}

function getSelectedAnswers(questionName) {
    const checkboxes = document.querySelectorAll(`input[name="${questionName}"]:checked`);
    const selected = Array.from(checkboxes).map(cb => cb.value).sort();
    return selected;
}

function arraysEqual(arr1, arr2) {
    if (arr1.length !== arr2.length) return false;
    return arr1.every((val, idx) => val === arr2[idx]);
}

function displayResults(results) {
    const questionTexts = {
        1: 'Which of the following are dynamically typed languages?',
        2: 'Which languages are commonly used for web development?',
        3: 'Which of these languages support functional programming paradigms?'
    };

    const answerLabels = {
        question1: {
            'python': 'Python',
            'javascript': 'JavaScript',
            'java': 'Java',
            'ruby': 'Ruby'
        },
        question2: {
            'html': 'HTML',
            'csharp': 'C#',
            'php': 'PHP',
            'rust': 'Rust'
        },
        question3: {
            'haskell': 'Haskell',
            'lisp': 'Lisp',
            'kotlin': 'Kotlin',
            'go': 'Go'
        }
    };

    let html = '';
    let score = 0;

    results.forEach(result => {
        const questionKey = `question${result.questionNumber}`;
        const labels = answerLabels[questionKey];

        if (result.isCorrect) {
            score++;
        }

        const statusClass = result.isCorrect ? 'success' : 'incorrect';
        const statusText = result.isCorrect ? '✓ Correct' : '✗ Incorrect';

        html += `
            <div class="result-item ${statusClass}">
                <div class="result-title">Question ${result.questionNumber}: ${statusText}</div>
                <div class="result-text"><strong>Question:</strong> ${questionTexts[result.questionNumber]}</div>
                <div class="result-text"><strong>Your answers:</strong> ${result.selected.length > 0 ? result.selected.map(v => labels[v]).join(', ') : 'No answers selected'}</div>
                <div class="result-text"><strong>Correct answers:</strong> ${result.correct.map(v => labels[v]).join(', ')}</div>
            </div>
        `;
    });

    // Add score summary
    const scorePercentage = Math.round((score / 3) * 100);
    html = `
        <div class="result-item success" style="border-left-color: var(--accent-color); margin-bottom: 24px;">
            <div class="result-title">Score: ${score}/3 (${scorePercentage}%)</div>
        </div>
    ` + html;

    resultsContent.innerHTML = html;
    quizForm.style.display = 'none';
    resultsDiv.style.display = 'block';
    resultsDiv.scrollIntoView({ behavior: 'smooth' });
}
